WITH RECURSIVE x6 AS (SELECT 0 AS x9 UNION ALL SELECT 2 * x1.x1.x3 + INTERVAL '1.1' SECOND + 2 FROM x10 WHERE x1.x1.x5 - INTERVAL '1.1' SECOND < 50 UNION ALL SELECT 2 * x1.x1.v40526 + INTERVAL '1' SECOND + 1 FROM x8 WHERE x1.x1.x5 - INTERVAL '1.1' SECOND < 50) SELECT 2 * x1.x1.x5 - INTERVAL '1.1' SECOND + 2, (@t2 := 1) + 0.000001, NOT x1.x1.x3 + INTERVAL '1.1' SECOND LIKE 'x' AS x0, x1.x1.x5 + INTERVAL '1' HOUR + 1.5e0 FROM v40543 AS x1 WHERE x1.x1.x5 - INTERVAL '1' HOUR > 1.5